use lg_core::{currency, AccountId, Date, Money, Txn};
use lg_fmt::Locale;
use lg_report::render::balance_report;
use lg_report::Summary;

#[test]
fn disc_l08() {
    let t = Txn::new(Date::ymd(2024, 3, 1), AccountId::parse("ativo:banco").unwrap(), "x", Money::of(123_456_789, "BRL"));
    let s = Summary::compute(&[&t], currency::brl(), None).unwrap();
    let out = balance_report(&s, &Locale::by_tag("pt-BR").unwrap());
    assert!(out.contains("R$ 1.234.567,89"), "{out}");
    let out = balance_report(&s, &Locale::by_tag("en-US").unwrap());
    assert!(out.contains("R$1,234,567.89"), "{out}");
}
